tool_input.command:
(PORT=4799 npx vite > /tmp/vite.log 2>&1 & echo $! > /tmp/vite.pid); sleep 3; cat /tmp/vite.log | tail -3
cat > /tmp/probe.mjs <<'EOF'
import { chromium } from "/Users/alitahseen/Demos/chess-test.wt/r1-D/node_modules/@playwright/test/index.mjs";
const b = await chromium.launch();
const errs=[];
for (const [w,h,scheme,touch] of [[390,844,"dark",true],[1280,800,"light",false]]) {
  const ctx = await b.newContext({viewport:{width:w,height:h},colorScheme:scheme,hasTouch:touch});
  const p = await ctx.newPage();
  p.on("console",m=>{if(m.type()==="error"||m.type()==="warning")errs.push(w+":"+m.text())});
  p.on("pageerror",e=>errs.push(String(e)));
  p.on("response",r=>{if(r.status()>=400)errs.push(w+" HTTP "+r.status()+" "+r.url())});
  for (const u of ["/","/?puzzle=12","/?puzzle=99","/?fen=bad"]) {
    await p.goto("http://localhost:4799"+u); await p.waitForSelector("[data-square]");
    const o = await p.evaluate(()=>document.documentElement.scrollWidth-innerWidth);
    console.log(w,u,"overflow",o, "bg", await p.evaluate(()=>getComputedStyle(document.body).backgroundColor));
  }
  await p.goto("http://localhost:4799/");
  await p.screenshot({path:`/tmp/s${w}.png`});
  if (touch) { // touch tap
    await p.locator('[data-square="e2"]').tap(); await p.locator('[data-square="e4"]').tap();
    console.log("touch tap e4:", await p.locator('[data-square="e4"] [data-piece]').count());
  }
  await ctx.close();
}
console.log("errors",errs);
await b.close();
EOF
node /tmp/probe.mjs
